QgsAttributeTableView::QgsAttributeTableView( QWidget *parent )
  : QTableView( parent )
{
  QgsSettings settings;
  restoreGeometry( settings.value( QStringLiteral( "BetterAttributeTable/geometry" ) ).toByteArray() );

